def transform(grid):
    # Find connected components of non-9 cells and return the top-left one
    R, C = len(grid), len(grid[0])
    # Find first cell != 9
    r0, c0 = -1, -1
    for r in range(R):
        for c in range(C):
            if grid[r][c] != 9:
                r0, c0 = r, c
                break
        if r0 != -1:
            break
    r1 = r0
    while r1 < R and grid[r1][c0] != 9:
        r1 += 1
    c1 = c0
    while c1 < C and grid[r0][c1] != 9:
        c1 += 1
    return [row[c0:c1] for row in grid[r0:r1]]

def transform(grid):
    # Border color is the color of grid[0][0].
    # Extract the first rectangular region not containing the border color.
    border = grid[0][0]
    R, C = len(grid), len(grid[0])
    r0, c0 = -1, -1
    for r in range(R):
        for c in range(C):
            if grid[r][c] != border:
                r0, c0 = r, c
                break
        if r0 != -1:
            break
    r1 = r0
    while r1 < R and grid[r1][c0] != border:
        r1 += 1
    c1 = c0
    while c1 < C and grid[r0][c1] != border:
        c1 += 1
    return [row[c0:c1] for row in grid[r0:r1]]
